INSERT INTO `product_reviews` VALUES (1,2,'yQhPrSKl2d',57,'7dow6NBmEAMRDJyD',5,'Trần Quang Lộc',NULL,'Màu sắc: Cam, Lưới: X5, Phản quang: Phản quang nhựa chuối caro, Size: Freesize, Trọng lượng: 80 gam',NULL,'Sản phẩm đẹp, bo viền chắc chắn.Lưới dày dặn không bị đứt gãy.','Chân thành cảm ơn anh đã ủng hộ sản phẩm ạ',NULL,NULL,'2024-05-12 22:00:00','2024-05-13 08:34:07','2024-05-13 08:34:07'),(2,2,'yQhPrSKl2d',69,'K1F7qnXKHZnuXKcU',4,'Kiều Thiên Phúc',NULL,'Màu sắc: Cam, Lưới: X5, Phản quang: Cam sọc 5cm, Size: Freesize, Trọng lượng: 80 gam',NULL,'Đường chỉ may chắc chắn, in cũng cẩn thận. Mới mua được 3 ngày cần trải nghiệm kỹ hơn sản phẩm.','Cảm ơn mình đã ủng hộ công ty GAK. Chúc mình có những trải nghiệm thật tốt với sản phẩm áo phản quang 3M bên em nhé.',NULL,NULL,'2024-05-12 22:00:00','2024-05-13 08:36:05','2024-05-13 08:36:05'),(3,2,'yQhPrSKl2d',57,'7dow6NBmEAMRDJyD',5,'Quenkhngnh',NULL,'Màu sắc: Cam, Lưới: X5, Phản quang: Phản quang nhựa chuối caro, Size: Freesize, Trọng lượng: 80 gam',NULL,'Chưa dùng nên chưa rõ, nhưng chất liệu cũng ổn, nhẹ nhàng! Màu sắc rõ ràng như hình, phản quang cũng sáng rõ. Giá cả hợp lý, còn độ bền thì chưa dám khẳng định vì vừa mua chưa dùng lâu! Shop giao hàng nhanh, hai ngày hơn là đã nhận được, anh em nên mua nhé!','Dạ em cảm ơn mình đã mua sản phẩm tại Công ty GAK. Mong rằng mình luôn có trải nghiệm tốt khi mua sắm áo phản quang kiêu 3M bên em ạ.',NULL,NULL,'2024-05-10 22:00:00','2024-05-13 09:11:09','2024-05-13 09:11:09'),(4,2,'yQhPrSKl2d',58,'sxdI9AYSz3Sni7EC',5,'khanghy89',NULL,'Màu sắc: Xanh dương (Bích), Lưới: X5, Phản quang: Phản quang nhựa chuối caro, Size: Freesize, Trọng lượng: 80 gam',NULL,'Nhận hàng nhanh chóng, sp đẹp như hình, giá rẻ mà đội ngũ tư vấn khá tận tâm. Mua cho ng lớn đi bộ trời tối xe máy dễ phát hiện.','Dạ, ông bà hay đi chạy bộ, đi dạo trong khu mặc cái này cũng đỡ lắm, xe cộ thấy từ xa, nếu mình cần in thông tin lên ngực áo bên em cũng hỗ trợ ạ.',NULL,NULL,'2024-05-10 22:00:00','2024-05-13 09:12:50','2024-05-13 09:12:50'),(5,2,'yQhPrSKl2d',69,'K1F7qnXKHZnuXKcU',5,'Quangthong.105',NULL,'Màu sắc: Cam, Lưới: X5, Phản quang: Cam sọc 5cm, Size: Freesize, Trọng lượng: 80 gam',NULL,'Áo khoác phản quang đẹp chất lượng sản phẩm tốt. Giá cả hợp lí. Nhân viên tư vấn kỹ. Nên mua','Dạ em cảm ơn mình rất nhiều ạ.',NULL,NULL,'2024-05-12 22:00:00','2024-05-13 09:13:50','2024-05-13 09:13:50'),(6,2,'yQhPrSKl2d',NULL,NULL,3.6,'_qm29zz4fc',NULL,NULL,NULL,'Đóng gói cẩn thận, giao hàng nhanh chóng, sp rất đẹp',NULL,NULL,NULL,'2024-05-10 22:00:00','2024-05-13 09:15:56','2024-05-13 09:15:56'),(7,2,'yQhPrSKl2d',NULL,NULL,5,'vuthanghn',NULL,NULL,NULL,'Đẹp...sáng...rất thích màu này....vải khá dễ giặt....ko biết lớp phản quang này giặt có bay ko cơ....5sao cho shop',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 09:16:25','2024-05-13 09:16:25'),(8,2,'yQhPrSKl2d',66,'cj44yWckFxAuGTzC',5,'Nguyễn Kim Thanh',NULL,'Màu sắc: Vàng, Lưới: X5, Phản quang: Phản quang nhựa chuối caro, Size: Freesize, Trọng lượng: 80 gam',NULL,'Sản phẩm dày dặn, độ phản quang tốt, thích hợp để đi tối, đêm, nên mua',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 11:03:09','2024-05-13 11:03:09'),(9,2,'yQhPrSKl2d',NULL,NULL,5,'Đào Bảo',NULL,NULL,NULL,'Áo chất đẹp lắm nhé, đường may cũng đẹp, mua đc giá sale tốt...',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 11:03:57','2024-05-13 11:03:57'),(10,2,'yQhPrSKl2d',NULL,NULL,5,'anh.dai.64',NULL,NULL,NULL,'Hàng chất lượng tốt , đúng với miêu tả , phản quang rất ok .',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 11:04:30','2024-05-13 11:04:30'),(11,2,'yQhPrSKl2d',NULL,NULL,4,'___lnt____',NULL,NULL,NULL,'Giao hàng nhanh, đóng gói hàng cẩn thận, chat lieu cực kì tốt luôn ạ',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 11:05:14','2024-05-13 11:05:14'),(12,2,'yQhPrSKl2d',NULL,NULL,5,'myhanhchu1102',NULL,NULL,NULL,'Chất liệu phản quang tốt, áo dày, mỗi tội ko có size to hơn, tuy vậy thì giá tốt',NULL,NULL,NULL,'2024-05-12 22:00:00','2024-05-13 11:05:32','2024-05-13